mapper.select:
SELECT * FROM ( /* 리뷰 */ SELECT p.post_id AS post_id, r.review_id AS targetId, r.review_title AS post_title, r.review_content AS post_content, p.created_at AS post_date, r.review_count AS view_count, r.review_like_count AS like_count, (SELECT COUNT(*) FROM comments c WHERE c.target_id = p.post_id AND c.target_type = 'COMMUNITY_REVIEW' AND c.is_deleted = 0) AS comment_count, 'COMMUNITY_REVIEW' AS targetType FROM community_post_review r JOIN post p ON p.post_id = r.post_id WHERE p.user_id = #{userId} AND p.is_deleted = 0
UNION ALL
/* 하우스포토 */ SELECT p.post_id AS post_id, h.housephoto_id AS targetId, h.housephoto_title AS post_title, h.housephoto_content AS post_content, p.created_at AS post_date, h.housephoto_count AS view_count, h.housephoto_like_count AS like_count, (SELECT COUNT(*) FROM comments c WHERE c.target_id = p.post_id AND c.target_type = 'COMMUNITY_HOUSEPHOTO' AND c.is_deleted = 0) AS comment_count, 'COMMUNITY_HOUSEPHOTO' AS targetType FROM community_post_housephoto h JOIN post p ON p.post_id = h.post_id WHERE p.user_id = #{userId} AND p.is_deleted = 0
UNION ALL
/* 하우스데코 */ SELECT p.post_id AS post_id, d.housedecoration_id AS targetId, d.housedecoration_title AS post_title, d.housedecoration_content AS post_content, p.created_at AS post_date, d.housedecoration_count AS view_count, d.housedecoration_like_count AS like_count, (SELECT COUNT(*) FROM comments c WHERE c.target_id = p.post_id AND c.target_type = 'COMMUNITY_HOUSEDECORATION' AND c.is_deleted = 0) AS comment_count, 'COMMUNITY_HOUSEDECORATION' AS targetType FROM community_post_housedecoration d JOIN post p ON p.post_id = d.post_id WHERE p.user_id = #{userId} AND p.is_deleted = 0 ) t ORDER BY t.post_date DESC LIMIT #{count} OFFSET #{start}
